\":\"metric\",\"metric\":\"dodges_without_damage\",\"targetValue\":3,\"window\":\"perTurn\",\"aggregation\":\"sum\",\"rewardCredits\":5,\"nameKey\":\"content.task.agile.name\",\"descKey\":\"content.task.agile.description\"},{\"id\":\"wealthy\",\"targetType\":\"metric\",\"metric\":\"credits\",\"targetValue\":15,\"window\":\"game\",\"aggregation\":\"maximum\",\"rewardCredits\":5,\"nameKey\":\"content.task.wealthy.name\",\"descKey\":\"content.task.wealthy.description\"},{\"id\":\"strongman\",\"targetType\":\"metric\",\"metric\":\"combat_strength\",\"targetValue\":7,\"window\":\"game\",\"aggregation\":\"maximum\",\"rewardCredits\":5,\"nameKey\":\"content.task.strongman.name\",\"descKey\":\"content.task.strongman.description\"},{\"id\":\"cripple\",\"targetType\":\"metric\",\"metric\":\"conditions\",\"targetValue\":3,\"window\":\"simultaneously\",\"aggregation\":\"maximum\",\"rewardCredits\":5,\"nameKey\":\"content.task.cripple.name\",\"descKey\":\"content.task.cripple.description\"},{\"id\":\"robot-owner\",\"targetType\":\"metric\",\"metric\":\"robot_reloaded\",\"targetValue\":2,\"window\":\"game\",\"aggregation\":\"sum\",\"rewardCredits\":5,\"nameKey\":\"content.task.robot-owner.name\",\"descKey\":\"content.task.robot-owner.description\"},{\"id\":\"lucky\",\"targetType\":\"metric\",\"metric\":\"roll_successes\",\"targetValue\":4,\"window\":\"simultaneously\",\"aggregation\":\"maximum\",\"rewardCredits\":5,\"nameKey\":\"content.task.lucky.name\",\"descKey\":\"content.task.lucky.description\"},{\"id\":\"hunter\",\"targetType\":\"metric\",\"metric\":\"enemies_killed\",\"targetValue\":2,\"window\":\"perTurn\",\"aggregation\":\"sum\",\"rewardCredits\":5,\"nameKey\":\"content.task.hunter.name\",\"descKey\":\"content.task.hunter.description\"},{\"id\":\"special\",\"targetType\":\"metric\",\"metric\":\"special_items_received\",\"targetValue\":1,\"window\":\"game\",\"aggregation\":\"sum\",\"rewardCredits\":5,\"nameKey\":\"content.task.special.name\",\"descKey\":\"content.task.special.description\"},{\"id\":\"abscessive\",\"targetType\":\"metric\",\"metric\":\"boils_popped\",\"targetValue\":6,\"window\":\"simultaneously\",\"aggregation\":\"maximum\",\"rewardCredits\":5,\"nameKey\":\"content.task.abscessive.name\",\"descKey\":\"content.task.abscessive.description\"},{\"id\":\"exterminator\",\"targetType\":\"metric\",\"metric\":\"strong_enemy_solo\",\"targetValue\":1,\"window\":\"perTurn\",\"aggregation\":\"sum\",\"rewardCredits\":5,\"nameKey\":\"content.task.exterminator.name\",\"descKey\":\"content.task.exterminator.description\"},{\"id\":\"fashionable\",\"targetType\":\"metric\",\"metric\":\"clothing_and_armor\",\"targetValue\":1,\"window\":\"simultaneously\",\"aggregation\":\"maximum\",\"rewardCredits\":5,\"nameKey\":\"content.task.fashionable.name\",\"descKey\":\"content.task.fashionable.description\"},{\"id\":\"merchant\",\"targetType\":\"metric\",\"metric\":\"supply_purchase_cost\",\"targetValue\":10,\"window\":\"game\",\"aggregation\":\"maximum\",\"rewardCredits\":5,\"nameKey\":\"content.task.merchant.name\",\"descKey\":\"content.task.merchant.description\"},{\"id\":\"lively\",\"targetType\":\"metric\",\"metric\":\"health_at_most\",\"targetValue\":1,\"window\":\"game\",\"aggregation\":\"maximum\",\"rewardCredits\":5,\"nameKey\":\"content.task.lively.name\",\"descKey\":\"content.task.lively.description\"}]},\"decks\":{\"conditions\":[\"malaise\",\"malaise\",\"malaise\",\"malaise\",\"malaise\",\"malaise\",\"malaise\",\"malaise\",\"malaise\",\"concussion\",\"concussion\",\"concussion\",\"concussion\",\"concussion\",\"concussion\",\"concussion\",\"concussion\",\"concussion\",\"nausea\",\"nausea\",\"nausea\",\"nausea\",\"nausea\",\"nausea\",\"nausea\",\"nausea\",\"nausea\",\"fracture\",\"fracture\",\"fracture\",\"fracture\",\"fracture\",\"fracture\",\"fracture\",\"fracture\",\"fracture\",\"shortness-of-breath\",\"shortness-of-breath\",\"shortness-of-breath\",\"shortness-of-breath\",\"shortness-of-breath\",\"shortness-of-breath\",\"shortness-of-breath\",\"shortness-of-breath\",\"shortness-of-breath\",\"adrenaline\",\"adrenaline\",\"adrenaline\",\"adrenaline\",\"adrenaline\"],\"events\":[\"cabin-noise\",\"vending-machine\",\"pile-of-things\",\"monster-nest\",\"corpse\",\"suitcases\",\"hatch-monster\",\"security-room\",\"exposed-wires\",\"monster-pack\",\"rope-hatch\",\"weapon-monster\",\"repair-cleaner\",\"countdown-trap\",\"scientist-report\",\"monster-corpse\",\"rubble\",\"two-crates\",\"huge-crate\",\"toolbox\",\"exoskeleton-terminal\",\"contraband-cache\",\"falling-monster\",\"collapsed-panel\",\"blood-trail\",\"ship-map\",\"cache-symbols\",\"scientist-case\",\"inventory-notes\",\"nest-room\",\"needle-box\",\"bloody-suitcase\",\"broken-drone\",\"radio-transmitter\",\"lights-out\",\"ventilation-failure\",\"gas-pipe\",\"vent-monster\",\"security-console\",\"cigarette-machine\",\"pack-sighting\",\"gas-cabin\",\"hatch-scrape\",\"oxygen-alarm\",\"survivor-scream\",\"child-cry\",\"female-whisper\",\"alcohol-crate\",\"supply-terminal\",\"trade-bot\",\"lockers\",\"body-pile\",\"junk-medical\",\"junk-credits\",\"junk-guitar\",\"shelf-equipment\",\"falling-beam\",\"meteor-stream\",\"fire\",\"monster-horde\",\"asteroid-alert\",\"horde-carry\",\"invasion-open-0\",\"invasion-open-1\",\"invasion-escape-pods-1\",\"invasion-armory-2\",\"invasion-reactor-3\",\"invasion-medical-bay-4\",\"invasion-crew-quarters-5\",\"invasion-laboratory-6\",\"invasion-storage-7\",\"invasion-engineering-control-post-8\",\"invasion-main-computer-9\",\"invasion-dining-hall-10\",\"invasion-flight-control-11\",\"invasion-morgue-12\",\"invasion-escape-pods-13\",\"invasion-armory-14\",\"invasion-reactor-15\",\"invasion-medical-bay-16\",\"invasion-crew-quarters-17\",\"invasion-laboratory-18\",\"invasion-storage-19\",\"invasion-engineering-control-post-20\",\"invasion-main-computer-21\",\"invasion-dining-hall-22\",\"invasion-flight-control-23\",\"invasion-morgue-24\"],\"storyQuests\":[\"quest-01\"]},\"characterNames\":{\"scientist\":{\"name\":\"Ученый\",\"diary\":\"Разумна Путимировна, личная запись 973:\\nПотрясающе! Просто потрясающе! Никто даже и представить не мог такой успех нашей экспедиции. Все собранные нами образцы уже перенесены на корабль и я не могу даже представить лица коллег на Земле. Исследование живых организмов с этой планеты будет несомненно самым крупным прорывом во многих областях науки. Все образцы продолжают жить даже лишенные пищи. Да что уж, они не погибают даже в вакууме! Мне так не терпится провести как можно больше опытов в своей лаборатории на Земле. Я чувствую, что волнение, переполняющее меня, пересилит даже криосон.\"},\"guard\":{\"name\":\"Охранник\",\"diary\":\"Градимир Здраславович, личная запись 481:\\n12845 шагов. Эта цифра еще долго будет мне сниться. Именно столько шагов требуется для ежедневного обхода периметра лагеря. Почти полтора года, 12845 шагов. Не так я представлял себе экспедицию на дикую планету. Даже местная фауна после первых нескольких попыток не приближается к лагерю ближе 800 метров. Даже по банкам пострелять не дают! Шум мешает этим халатам работать, видите ли. Чистка табельного оружия и алкоголь единственное развлечение на этой гребаной планете. Я рассчитывал, что это задание будет вызовом! Ничего, следующий контракт я буду выбирать куда тщательней.\"},\"mechanic\":{\"name\":\"Механик\",\"diary\":\"Часлав Тихомирович, личная запись 307:\\nБоже, как же я вчера набрался. Хорошо что у меня не так много вещей, а инструменты уже погружены на корабль.\\n\\nЧаслав Тихомирович, личная запись 308:\\nЭто была тяжкая вылазка на природу, но я рад, что она закончилась. Последние дни мне уж совсем не по себе. Черт, ну хоть не нужно дежурить весь полет! Я очень надеюсь, что эти криворукие придурки ничего не сломают, чтобы у них не было повода меня будить до возвращения на Землю.\"},\"worker\":{\"name\":\"Рабочий\",\"diary\":\"Трудомир Младаныч, личная запись 125:\\nС каждым днем я все меньше радуюсь тому, что получил эту работу. По крайней мере сумма, которую мне предложили, уже точно не стоит того. Не знаю, что решат эти заучки, распираемые от собственной важности, но я бы точно не стал колонизировать эту планету. Буйство красок и растительности должно приносить радость, но меня не покидает чувство тревоги. А еще эти гребаные запечатанные ящики, которые мы уже третьи сутки грузим на корабль перед отправлением. Не знаю, что в них за образцы, но от одного только прикосновения я весь холодею. Ничего, уже завтра я проснусь дома...\"},\"hauler\":{\"name\":\"Таскала\",\"diary\":\"Драган Домославич, личная запись 203:\\nВсего через полгода, которые пройдут для меня как пара дней, я буду сказочно богат. Никто и не заметит пропажи нескольких образцов, особенно учитывая, что именно я и отвечаю за инвентарный учет.\\n\\nДраган Домославич, личная запись 204:\\nЗавтра я уже проснусь дома и при деньгах. Тайник запечатан, все проверено трижды. Осталось только незаметно сообщить «друзьям» на Земле о вылете, и можно расслабиться. Пожалуй, праздничный бокальчик пива сегодня вечером будет более чем уместен.\"},\"healer\":{\"name\":\"Знахарь\",\"diary\":\"Путимир Стоумич, личная запись 681:\\nС войны я не испытывал такого стресса. Запаса медикаментов может не хватить на обратный путь, учитывая количество больных членов команды.\\n\\nПутимир Стоумич, личная запись 722:\\nМесяц моего дежурства после нашего отбытия домой. Пришлось разбудить коллег из криосна, так как всем больным стало хуже практически одновременно. Совокупность их симптомов... Они просто не могут быть совместимы с жизнью, но они все еще в сознании.\\n\\nПутимир Стоумич, личная запись 723:\\nСитуация стабилизировалась и раз уж сменщики уже здесь, я смогу спокойно поспать до пересменки.\"},\"engineer\":{\"name\":\"Инженер\",\"diary\":\"Всеслав Гораздович, личная запись 218:\\nСраные недоумки! Это уже 4 грузовой дроид за эту неделю! Я конечно понимаю, что все торопятся к отправке по графику, но это последний сервопривод. Еще раз эти ботаники перегрузят моих малышей и будут таскать свои гребаные образцы на собственном горбу!\\n\\nВсеслав Гораздович, личная запись 219:\\nЗавид принес мне бутылку отличной браги в благодарность за не совсем согласованный апдейт его бота-уборщика. Ну хоть будет, чем отметить наше возвращение, пока этот чудик будет развлекаться со своей новой игрушкой у себя в каюте.\"},\"astronaut\":{\"name\":\"Астронавт\",\"diary\":\"Изяслав Казимирович, личная запись 120:\\nЧерт возьми, почему полет назад не может быть тихим и спокойным, мать его! Еще немного и я сам что-нибудь сломаю, только чтобы был повод выбраться на обшивку и побыть в тишине.\\n\\nИзяслав Казимирович, личная запись 121:\\nНаконец бесконечные стоны из лазарета прекратились. Хоть высплюсь сегодня.\\n\\nИзяслав Казимирович, личная запись 122:\\nОпять какая-то паника у этих докторишек, чтоб их! Хорошо хоть, что завтра уже не моя вахта, надеюсь за следующий месяц они успокоятся или я за себя не ручаюсь...\"}}}";
